local DibberMaker = {}
local PRODUCTS = {
    iron_dibber = { name = "Železni sadilnik za seme", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni sadilnik za seme za vrtnarje." },
    bronze_dibber = { name = "Bronast sadilnik za seme", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast sadilnik za seme za vrtnarje." },
    silver_dibber = { name = "Srebrn sadilnik za seme", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn sadilnik za seme za vrtnarje." },
    gilded_dibber = { name = "Pozlačen sadilnik za seme", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen sadilnik za seme za vrtnarje." },
    jewel_set_dibber = { name = "Draguljast sadilnik za seme", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast sadilnik za seme za vrtnarje." },
    royal_sovereign_dibber = { name = "Kraljevski suveren sadilnik za seme", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren sadilnik za seme z biseri za krono." },
}
local BUILDINGS = {
    dibber_workshop = { name = "Dibber delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    dibber_house = { name = "Dibber hiša", cost = { gold = 1185, wood = 370, stone = 265, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_dibber_atelier = { name = "Mojstrski dibber atelje", cost = { gold = 2975, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_dibber_palace = { name = "Suverena dibber palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
DibberMaker.ironStock=14; DibberMaker.bronzeStock=12; DibberMaker.woodStock=16; DibberMaker.leatherStock=8; DibberMaker.silverStock=8; DibberMaker.goldStock=6; DibberMaker.jewelStock=4; DibberMaker.pearlStock=4
DibberMaker.productStock = {}; DibberMaker.buildings = {}; DibberMaker.maker = nil; DibberMaker.activeMaking = {}; DibberMaker.totalProducts = 0; DibberMaker.dayTimer = 0
function DibberMaker.init() DibberMaker.ironStock=14; DibberMaker.bronzeStock=12; DibberMaker.woodStock=16; DibberMaker.leatherStock=8; DibberMaker.silverStock=8; DibberMaker.goldStock=6; DibberMaker.jewelStock=4; DibberMaker.pearlStock=4; DibberMaker.productStock={}; DibberMaker.buildings={}; DibberMaker.maker=nil; DibberMaker.activeMaking={}; DibberMaker.totalProducts=0; DibberMaker.dayTimer=0; print("[DibberMaker] Royal Dibber Maker System initialized (6 products, 4 buildings)") end
function DibberMaker.hireMaker(n,s) s=s or math.random(55,90); local c=570+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; DibberMaker.maker={name=n or ("Sadilnikar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Sadilnikar najet: %s (spretnost: %d)",DibberMaker.maker.name,s),"success") end; return true end
function DibberMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function DibberMaker.build(id) local ok,e=DibberMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(DibberMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function DibberMaker.getQualityBonus() local b=0; for _,bd in ipairs(DibberMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function DibberMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and DibberMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and DibberMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and DibberMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and DibberMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and DibberMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and DibberMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and DibberMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and DibberMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #DibberMaker.buildings==0 then return false,"Potrebna sadilna delavnica" end; if not DibberMaker.maker then return false,"Potreben sadilnikar" end; return true end
function DibberMaker.make(pt,qty) qty=qty or 1; local ok,e=DibberMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then DibberMaker.ironStock=DibberMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then DibberMaker.bronzeStock=DibberMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then DibberMaker.woodStock=DibberMaker.woodStock-d.woodCost*qty end; if d.leatherCost then DibberMaker.leatherStock=DibberMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then DibberMaker.silverStock=DibberMaker.silverStock-d.silverCost*qty end; if d.goldCost then DibberMaker.goldStock=DibberMaker.goldStock-d.goldCost*qty end; if d.jewelCost then DibberMaker.jewelStock=DibberMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then DibberMaker.pearlStock=DibberMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if DibberMaker.maker then t=math.max(1,t-math.floor(DibberMaker.maker.skill/13)) end; table.insert(DibberMaker.activeMaking,{id="dibber_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function DibberMaker.completeMaking(m) local q=1.0+(DibberMaker.getQualityBonus()/100); if DibberMaker.maker then q=q+(DibberMaker.maker.skill/140) end; q=math.min(2.5,q); DibberMaker.productStock[m.productType]=(DibberMaker.productStock[m.productType] or 0)+m.quantity; DibberMaker.totalProducts=DibberMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if DibberMaker.maker then DibberMaker.maker.itemsMade=DibberMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then DibberMaker.maker.skill=math.min(100,DibberMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Sadilnik izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"dibber.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function DibberMaker.update(dt) if not _G.state then return end; DibberMaker.dayTimer=DibberMaker.dayTimer+dt; if DibberMaker.dayTimer>=30 then DibberMaker.dayTimer=0; for i=#DibberMaker.activeMaking,1,-1 do local m=DibberMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then DibberMaker.completeMaking(m); table.remove(DibberMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(DibberMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if DibberMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function DibberMaker.getStats() return {ironStock=DibberMaker.ironStock,bronzeStock=DibberMaker.bronzeStock,woodStock=DibberMaker.woodStock,leatherStock=DibberMaker.leatherStock,silverStock=DibberMaker.silverStock,goldStock=DibberMaker.goldStock,jewelStock=DibberMaker.jewelStock,pearlStock=DibberMaker.pearlStock,productStock=DibberMaker.productStock,numBuildings=#DibberMaker.buildings,hasMaker=DibberMaker.maker~=nil,makerName=DibberMaker.maker and DibberMaker.maker.name or "—",makerSkill=DibberMaker.maker and DibberMaker.maker.skill or 0,activeMaking=#DibberMaker.activeMaking,totalProducts=DibberMaker.totalProducts} end
return DibberMaker
